validator:
function validate(input) {
  const [{ UserActivity = [] }] = input;
  const seen = new Set(), types = ['free_trial', 'paid', 'cancelled'];
  for (const [user, day, type, minutes] of UserActivity) {
    if ([user, day, type, minutes].includes(null)) return 'No value in UserActivity may be null.';
    if (!types.includes(type)) return `activity_type ${type} must be free_trial, paid or cancelled.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return `activity_date ${day} must look like 2023-01-31.`;
    if (!Number.isInteger(minutes) || minutes < 0) return `activity_duration ${minutes} must be a non-negative whole number.`;
    const key = `${user}|${day}|${type}`;
    if (seen.has(key)) return `(${user}, ${day}, ${type}) appears twice in UserActivity.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  const day = i => { const d = new Date(Date.UTC(2023, 0, 1 + i)); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`; };
  const minutes = () => small ? pick([0, 15, 25, 30, 45, 50, 60, 75, 90]) : Math.floor(rand() * 121);
  // Distinct sorted day offsets within [from, from + span).
  const days = (from, span, count) => { const set = new Set(); while (set.size < count) set.add(from + Math.floor(rand() * span)); return [...set].sort((a, b) => a - b); };
  const limit = small ? Math.floor(rand() * 9) : 2000;
  const ids = small ? [1, 2, 3, 4, 5, 6] : Array.from({ length: 400 }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const UserActivity = [];
  // At most 7 rows of one type per user, so no average lands exactly halfway between two cents.
  for (const user of ids) {
    if (UserActivity.length >= limit) break;
    const most = small ? 3 : 7, start = Math.floor(rand() * 300);
    const trials = rand() < 0.1 ? 0 : 1 + Math.floor(rand() * most);
    const paid = rand() < 0.35 ? 0 : 1 + Math.floor(rand() * most);
    const rows = [];
    for (const d of days(start, 7, trials)) rows.push([user, day(d), 'free_trial', minutes()]);
    for (const d of days(start + 7, 20, paid)) rows.push([user, day(d), 'paid', minutes()]);
    if (rand() < 0.4) rows.push([user, day(start + 30), 'cancelled', 0]);
    for (const row of rows) if (UserActivity.length < limit) UserActivity.push(row);
  }
  for (let i = UserActivity.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [UserActivity[i], UserActivity[j]] = [UserActivity[j], UserActivity[i]]; }
  return [{ UserActivity }];
}
